/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  Easing,
  random,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadFont = makeLoadFont('Inter');

const { fontFamily: interFamily } = loadFont();



export type LiquidGlassComparisonProps = Record<string, any>;

const LiquidGlassComparison: React.FC<LiquidGlassComparisonProps> = ({
  backgroundColor = "#0a0a0f",
  transparentBackground = false,
  durationInSeconds = 10,
  glassOpacity = 0.15,

  title = "Best Asset for Wealth Transfer",
  subtitle = "Cumulative Growth (2010-2025)",

  series = [
    {
      name: "Watches",
      color: "#d4af37",
      isMain: true,
      dataPoints: [
        { year: "2010", value: 100 },
        { year: "2013", value: 140 },
        { year: "2016", value: 210 },
        { year: "2019", value: 290 },
        { year: "2022", value: 410 },
        { year: "2025", value: 520 },
      ],
    },
    {
      name: "Stocks",
      color: "#4a90e2",
      isMain: false,
      dataPoints: [
        { year: "2010", value: 100 },
        { year: "2013", value: 130 },
        { year: "2016", value: 160 },
        { year: "2019", value: 200 },
        { year: "2022", value: 240 },
        { year: "2025", value: 310 },
      ],
    },
    {
      name: "Real Estate",
      color: "#e24a4a",
      isMain: false,
      dataPoints: [
        { year: "2010", value: 100 },
        { year: "2013", value: 115 },
        { year: "2016", value: 130 },
        { year: "2019", value: 155 },
        { year: "2022", value: 190 },
        { year: "2025", value: 220 },
      ],
    }
  ],
}) => {
  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Chart Dimensions & Grid Constraints - Adapted for vertical 9:16 layout
  const minX = width * 0.15;
  const maxX = width * 0.85;
  const minY = height * 0.75;
  const maxY = height * 0.4;

  const maxValue = Math.max(
    ...series.flatMap((s) => s.dataPoints.map((d) => d.value)),
    1
  );

  // Map data to coordinates for each series
  const seriesData = useMemo(() => {
    return series.map((s) => {
      const segs = Math.max(1, s.dataPoints.length - 1);
      const sDx = (maxX - minX) / segs;

      const points = s.dataPoints.map((d, i) => ({
        x: minX + i * sDx,
        y: minY - (d.value / maxValue) * (minY - maxY),
        value: d.value,
        year: d.year,
      }));

      let lineStr = `M ${points[0].x} ${points[0].y}`;
      let areaStr = `M ${points[0].x} ${minY} L ${points[0].x} ${points[0].y}`;

      for (let i = 0; i < segs; i++) {
        const p0 = points[i];
        const p3 = points[i + 1];
        const segDx = p3.x - p0.x;
        const cp1x = p0.x + segDx / 3;
        const cp1y = p0.y;
        const cp2x = p3.x - segDx / 3;
        const cp2y = p3.y;

        const curve = ` C ${cp1x} ${cp1y}, ${cp2x} ${cp2y}, ${p3.x} ${p3.y}`;
        lineStr += curve;
        areaStr += curve;
      }
      areaStr += ` L ${points[segs].x} ${minY} Z`;

      return { ...s, points, dLine: lineStr, dArea: areaStr, segs };
    });
  }, [series, minX, maxX, minY, maxY, maxValue]);

  // Main series tracking target
  const mainSeries = seriesData.find((s) => s.isMain) || seriesData[0];
  const mainColor = mainSeries?.color || "#ffffff";

  // Render sort (main series drawn last to stay on top)
  const sortedSeriesForRender = [...seriesData].sort((a, b) =>
    a.isMain === b.isMain ? 0 : a.isMain ? 1 : -1
  );

  // Timings
  const lineStart = 40;
  const lineDuration = 110;

  // Interpolate Progress
  const getProgress = (f: number) =>
    interpolate(f, [lineStart, lineStart + lineDuration], [0, 1], {
      easing: Easing.inOut(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

  const lineProgress = getProgress(frame);

  // Cubic Bezier interpolation logic for tracking dots dynamically
  const getInterpolatedState = (
    pts: { x: number; y: number; value: number; year: string }[],
    prog: number
  ) => {
    if (prog <= 0) return { ...pts[0] };
    if (prog >= 1) return { ...pts[pts.length - 1] };

    const tTotal = prog * (pts.length - 1);
    const i = Math.floor(tTotal);
    const t = tTotal - i;
    
    // Safety check ensuring we don't index out of bounds on edges
    const safeI = Math.min(i, pts.length - 2);
    
    const p0 = pts[safeI];
    const p3 = pts[safeI + 1];

    // Cubic bezier easing function matching the horizontal tangents
    const easeFactor0 = 1 - 3 * t * t + 2 * t * t * t;
    const easeFactor3 = 3 * t * t - 2 * t * t * t;

    return {
      x: p0.x + t * (p3.x - p0.x),
      y: p0.y * easeFactor0 + p3.y * easeFactor3,
      value: p0.value * easeFactor0 + p3.value * easeFactor3,
    };
  };

  // Camera State Logic (Pan and Zoom to Track Main Line's Progression)
  const getCameraState = (f: number) => {
    const prog = getProgress(f);
    const mainDot = getInterpolatedState(mainSeries.points, prog);

    const zoomProg = interpolate(f, [lineStart, lineStart + 50], [0, 1], {
      easing: Easing.inOut(Easing.cubic),
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    });

    const scale = interpolate(zoomProg, [0, 1], [1, 1.15]); // Modest zoom to keep everything in view
    const focalX = interpolate(zoomProg, [0, 1], [width / 2, mainDot.x]);
    const focalY = interpolate(zoomProg, [0, 1], [height / 2, height / 2]); // Lock Y to center all series securely

    return {
      x: width / 2 - focalX * scale,
      y: height / 2 - focalY * scale,
      scale,
    };
  };

  const cam = getCameraState(frame);

  // Environmental Opacities
  const baseGridOpacity = interpolate(frame, [0, 30], [0, 1], { extrapolateRight: "clamp" });
  const pulse = interpolate(Math.sin(frame / 15), [-1, 1], [0.1, 0.4]);
  const finalGridOpacity = baseGridOpacity * pulse;

  // Background Particles
  const particles = useMemo(() => {
    return Array.from({ length: 60 }).map((_, i) => ({
      id: i,
      x: random(`x-${i}`) * width * 3 - width,
      y: random(`y-${i}`) * height * 3 - height,
      size: random(`s-${i}`) * 2 + 1,
      speed: random(`sp-${i}`) * 0.3 + 0.1,
      opacity: random(`o-${i}`) * 0.1 + 0.02,
    }));
  }, [width, height]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: interFamily, overflow: "hidden" }}>
      {/* Dynamic Camera Tracking Wrapper */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          transform: `translate(${cam.x}px, ${cam.y}px) scale(${cam.scale})`,
          transformOrigin: "0 0",
          transition: "none",
          overflow: "visible",
        }}
      >
        {/* Infinite Space Grid (expanded heavily so panning doesn't reveal edges) */}
        <div
          style={{
            position: "absolute",
            left: -width * 2,
            top: -height * 2,
            width: width * 5,
            height: height * 5,
            opacity: finalGridOpacity,
            backgroundImage: `linear-gradient(rgba(255, 255, 255, 0.06) 1px, transparent 1px), linear-gradient(90deg, rgba(255, 255, 255, 0.06) 1px, transparent 1px)`,
            backgroundSize: "60px 60px",
            backgroundPosition: "center",
            transition: "none",
          }}
        />

        {/* Dynamic Center Ambient Glow */}
        <div
          style={{
            position: "absolute",
            top: height * 0.3,
            left: width * 0.5 - 600,
            width: 1200,
            height: 800,
            background: `radial-gradient(circle, ${mainColor}11 0%, transparent 60%)`,
            opacity: baseGridOpacity,
            transition: "none",
          }}
        />

        {/* Particles rendering in a much wider range */}
        <div style={{ position: "absolute", left: 0, top: 0, overflow: "visible", pointerEvents: "none" }}>
          {particles.map((p) => {
            const yOffset = frame * p.speed;
            return (
              <div
                key={p.id}
                style={{
                  position: "absolute",
                  left: p.x,
                  top: p.y - yOffset,
                  width: p.size,
                  height: p.size,
                  background: "white",
                  opacity: p.opacity,
                  borderRadius: "50%",
                  transition: "none",
                }}
              />
            );
          })}
        </div>

        {/* Horizontal Axis Lines */}
        {[0, 0.25, 0.5, 0.75, 1].map((ratio) => {
          const yPos = minY - ratio * (minY - maxY);
          return (
            <div
              key={ratio}
              style={{
                position: "absolute",
                left: minX - 50,
                top: yPos,
                width: maxX - minX + 100,
                height: 1,
                background: "rgba(255,255,255,0.06)",
                opacity: interpolate(frame, [15, 40], [0, 1]),
                transition: "none",
              }}
            />
          );
        })}

        {/* Chart SVG Canvas */}
        <svg width={width} height={height} style={{ position: "absolute", inset: 0, overflow: "visible" }}>
          <defs>
            {sortedSeriesForRender.map((s) => (
              <linearGradient
                key={`grad-${s.name}`}
                id={`areaGrad-${s.name.replace(/\s/g, "")}`}
                x1="0"
                y1="0"
                x2="0"
                y2="1"
              >
                <stop
                  offset="0%"
                  stopColor={s.color}
                  stopOpacity={s.isMain ? glassOpacity + 0.25 : glassOpacity}
                />
                <stop offset="100%" stopColor={s.color} stopOpacity={0.0} />
              </linearGradient>
            ))}

            <filter id="glow" x="-20%" y="-20%" width="140%" height="140%">
              <feGaussianBlur stdDeviation="8" result="coloredBlur" />
              <feMerge>
                <feMergeNode in="coloredBlur" />
                <feMergeNode in="SourceGraphic" />
              </feMerge>
            </filter>
          </defs>

          {/* Reveal Clip Path for drawing animation */}
          <clipPath id="chartClip">
            <rect
              x={0}
              y={0}
              width={minX + lineProgress * (maxX - minX + 100)}
              height={height}
            />
          </clipPath>

          <g clipPath="url(#chartClip)">
            {sortedSeriesForRender.map((s) => (
              <g key={s.name}>
                {/* Liquid Glass Area */}
                <path
                  d={s.dArea}
                  fill={`url(#areaGrad-${s.name.replace(/\s/g, "")})`}
                />
                {/* Glowing Outer Path */}
                <path
                  d={s.dLine}
                  fill="none"
                  stroke={s.color}
                  strokeWidth={s.isMain ? 8 : 4}
                  filter={s.isMain ? "url(#glow)" : undefined}
                  strokeOpacity={s.isMain ? 0.7 : 0.4}
                />
                {/* Crisp Inner Core Path */}
                <path
                  d={s.dLine}
                  fill="none"
                  stroke={s.isMain ? "#ffffff" : s.color}
                  strokeWidth={s.isMain ? 3 : 2}
                  opacity={s.isMain ? 1 : 0.8}
                />
              </g>
            ))}
          </g>
        </svg>

        {/* Tracking Dots & Labels (Replacing Numbers with Series Names) */}
        {sortedSeriesForRender.map((s, idx) => {
          const currentDot = getInterpolatedState(s.points, lineProgress);
          return (
            <div
              key={`dot-${idx}`}
              style={{
                position: "absolute",
                left: currentDot.x,
                top: currentDot.y,
                transition: "none",
                pointerEvents: "none",
                opacity: lineProgress > 0.01 ? 1 : 0,
                zIndex: s.isMain ? 10 : 1,
              }}
            >
              {/* Glowing Orb */}
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: 0,
                  transform: "translate(-50%, -50%)",
                  width: s.isMain ? 16 : 10,
                  height: s.isMain ? 16 : 10,
                  borderRadius: "50%",
                  backgroundColor: s.isMain ? "#fff" : s.color,
                  boxShadow: s.isMain
                    ? `0 0 20px 8px ${s.color}, inset 0 0 4px rgba(0,0,0,0.5)`
                    : `0 0 10px 2px ${s.color}`,
                  transition: "none",
                }}
              />

              {/* Name Readout flying above dot */}
              <div
                style={{
                  position: "absolute",
                  left: 0,
                  top: s.isMain ? -50 : -35,
                  transform: "translateX(-50%)",
                  color: s.isMain ? "#fff" : s.color,
                  fontSize: s.isMain ? 32 : 20,
                  fontWeight: s.isMain ? 700 : 600,
                  fontFamily: interFamily,
                  textShadow: "0 4px 16px rgba(0,0,0,0.8)",
                  transition: "none",
                  whiteSpace: "nowrap",
                  opacity: s.isMain ? 1 : 0.8,
                }}
              >
                {s.name}
              </div>
            </div>
          );
        })}

        {/* X-Axis Labels (Years) - Derived from the main/first series */}
        {seriesData[0]?.points.map((p, i) => {
          const itemSegments = seriesData[0].segs;
          // Reveal label just as the line approaches it
          const itemProgress = interpolate(
            lineProgress * itemSegments,
            [i - 0.5, i],
            [0, 1],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          return (
            <div
              key={p.year}
              style={{
                position: "absolute",
                left: p.x,
                top: minY + 30 + interpolate(itemProgress, [0, 1], [15, 0]),
                transform: "translateX(-50%)",
                opacity: itemProgress,
                color: "rgba(255,255,255,0.7)",
                fontSize: 20,
                fontWeight: 600,
                fontFamily: interFamily,
                transition: "none",
              }}
            >
              {p.year}
            </div>
          );
        })}
      </div>

      {/* Floating HUD Title (Outside camera tracking to remain anchored/cinematic) */}
      <div
        style={{
          position: "absolute",
          top: height * 0.15, // Pushed down slightly into safe zone for 9:16
          width: "100%",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          opacity: interpolate(frame, [10, 30], [0, 1], { extrapolateRight: "clamp" }),
          transition: "none",
          pointerEvents: "none",
        }}
      >
        <div
          style={{
            color: "white",
            fontSize: 52,
            fontWeight: 700,
            fontFamily: interFamily,
            textShadow: "0 4px 16px rgba(0,0,0,0.6)",
            letterSpacing: "-0.02em",
            textAlign: "center",
            maxWidth: "90%",
            lineHeight: 1.2,
          }}
        >
          {title}
        </div>
        <div
          style={{
            color: mainColor,
            fontSize: 28,
            fontWeight: 600,
            fontFamily: interFamily,
            marginTop: 16,
            textShadow: "0 2px 8px rgba(0,0,0,0.5)",
            textAlign: "center",
          }}
        >
          {subtitle}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default LiquidGlassComparison;